		} else {
			nerProvider, err := icme.NewNERProvider(logger)
			if err != nil {
				log.Printf("Warning: Failed to initialize ICME NER provider: %v", err)
			} else {
				faissManager, err := icme.NewFAISSIndexManager(dbManager, logger)
				if err != nil {
					log.Printf("Warning: Failed to initialize ICME FAISS manager: %v", err)
				} else {
					graphEngine := icme.NewTemporalHypergraph(
						icmeConfig.GraphWindowSize,
						icmeConfig.GraphMaxNodes,
						logger,
					)

					// Wire KNIRVGRAPH into the Cognitive Engine for ontological data organization
					cognitiveEngine.SetKNIRVGRAPHEngine(graphEngine, logger)
					log.Println("CognitiveEngine: KNIRVGRAPH temporal hypergraph wired for ontology indexing")

					intentRegistry, err := icme.NewIntentRegistry(dbManager, logger)
					if err != nil {
						log.Printf("Warning: Failed to initialize ICME intent registry: %v", err)
					} else {
						factualityAdapter := icme.NewFactualityAdapter(
							"",
							intentRegistry,
							dbManager,
							logger,
						)

						delegation := icme.NewDelegationFramework(intentRegistry, logger)

						alignmentLoop := icme.NewAlignmentLoop(
							intentRegistry,
							factualityAdapter,
							icmeConfig.AlignmentEvalInterval,
							icmeConfig.DriftThreshold,
							logger,
						)

						signalRouter := icme.NewSignalRouter(
							intentRegistry,
							nerProvider,
							embeddingProvider,
							graphEngine,
							faissManager,
							nil,
							logger,
						)

						searchEngine := icme.NewHybridSearchEngine(
							faissManager,
							graphEngine,
							intentRegistry,
							logger,
						)

						icmeService = icme.NewService(
							intentRegistry,
							graphEngine,
							faissManager,
							searchEngine,
							delegation,
							alignmentLoop,
							signalRouter,
							logger,
							dbManager,
						)
						if validationChainClient != nil {
							icmeService.SetValidationChainClient(validationChainClient)
							log.Println("ICME: validation chain client wired during initialization")
						}

						icmeCtx, icmeCancel := context.WithCancel(context.Background())
						go signalRouter.Start(icmeCtx)
						go alignmentLoop.Start(icmeCtx)
						_ = icmeCancel

						log.Println("ICME Service initialized successfully")
					}
				}
			}
		}
	} else {
		log.Println("ICME Service disabled via configuration")
	}

	if transactionChainClient != nil {
		if dveCreationService != nil {
			dveCreationService.SetTransactionChainClient(transactionChainClient)
			log.Println("Transaction chain client integrated with DVE creation service")
		}
		if dveRentalService != nil {
			dveRentalService.SetTransactionChainClient(transactionChainClient)
			log.Println("Transaction chain client integrated with DVE rental service")
		}
	}

	// Wire KNIRVAGENT DVE Supervisor into DVE creation service
	if dveCreationService != nil && knirvagentMgr != nil {
		dveCreationService.SetKnirvagentManager(knirvagentMgr)
		log.Println("KNIRVAGENT supervisor wired into DVE creation service")
	}

	// Wire DVE Manager into DVE creation service so new DVEs are registered
	// in the nodes list immediately when created.
	if dveCreationService != nil && dveManager != nil {
		dveCreationService.SetDveManager(dveManager)
		log.Println("DVE manager wired into DVE creation service")
	}

	// Initialize Nexus Memory Fabric
	nexusAllocator := memory.DefaultAllocator
	nexusServer := nexus.NewNexusMemoryServer(nexusAllocator)
	if activeMemoryService != nil {
		nexusServer.SetMemoryProvider(activeMemoryService)
	}
	if err := nexusServer.StartGuardian(); err != nil {
		log.Printf("Warning: Failed to start Nexus Guardian (eBPF): %v", err)
	}

	// ============================================
	// Production Services (Phase 3, 4, 8)
	// ============================================

	// Initialize EventBroadcaster for comprehensive WebSocket event streaming
	eventBroadcaster := websocket.NewEventBroadcaster(nil)
	eventBroadcaster.Start()
	log.Println("EventBroadcaster initialized")

	// Initialize SecretManager for session-based secret management
	secretManager := secrets.NewSecretManager(dbManager)
	secretManager.SetEncryptionKey([]byte(cfg.Security.JWTSecret))
	if err := secretManager.LoadSecrets(); err != nil {
		log.Printf("Warning: Failed to load secrets: %v", err)
	}
	if err := secretManager.LoadSessions(); err != nil {
		log.Printf("Warning: Failed to load secret sessions: %v", err)
	}
	log.Println("SecretManager initialized")

	// Initialize WorkflowService for real workflow execution orchestration
	workflowService := workflow.NewWorkflowService(dbManager)
	workflowService.SetDVEManager(dveManager)
	workflowService.SetValidationCore(validationCore)
	dveTaskExecutor := workflow.NewDVETaskExecutor(dveManager, validationCore)
	if validationChainClient != nil {
		dveTaskExecutor.SetValidationChainClient(validationChainClient)
	}
	workflowService.RegisterExecutor("validation", dveTaskExecutor)
	workflowService.SetEventBroadcaster(eventBroadcaster)
	if err := workflowService.LoadExecutionsFromDB(); err != nil {
		log.Printf("Warning: Failed to load workflow executions: %v", err)
	}
	log.Println("WorkflowService initialized")

	// Initialize GuardrailManager for dynamic guardrails and policy enforcement
	guardrailManager := guardrails.NewDynamicGuardrailManager(dbManager)
	guardrailManager.SetEventBroadcaster(eventBroadcaster)
	if err := guardrailManager.LoadConfigurations(); err != nil {
		log.Printf("Warning: Failed to load guardrail configurations: %v", err)
	}
	if err := guardrailManager.LoadOntologyRules(); err != nil {
		log.Printf("Warning: Failed to load ontology rules: %v", err)
	}

	// ── Resolution pipeline ───────────────────────────────────────────────────

	// Create infrastructure adapter for real remediation actions
	infraAdapter := wasm.NewServerInfrastructureAdapter(
		dveManager,
		ebpfManager,
		func(eventType, source, message string) {
			if eventBroadcaster != nil {
				eventBroadcaster.EmitPolicyViolation("", source, eventType, message)
			}
			log.Printf("[resolution-infra] %s/%s: %s", eventType, source, message)
		},
	)
	log.Println("ServerInfrastructureAdapter created for remediation")

	// Create the production remediation sink (real infrastructure actions)
	productionSink := wasm.NewProductionRemediationSink(infraAdapter)
	log.Println("ProductionRemediationSink initialized")

	// Create the BadgeConfigResolver — replaces the WASM module pipeline
	// with a simple in-memory badge config lookup keyed by ontology tags.
	configResolver := wasm.NewBadgeConfigResolver(productionSink)

	// Register the resolution function for all 8 remediation action names.
	resolveFn := func(ctx context.Context, v *cognitiveengine.PolicyViolation) error {
		signal := &wasm.ResolutionSignal{
			DVEID:   v.DVEID,
			NodeID:  v.NodeID,
			BadgeID: v.BadgeID,
		}
		_, err := configResolver.Resolve(ctx, signal)
		return err
	}
	remediationActions := []string{
		"quarantine_node", "redistribute_tasks", "scale_resources",
		"kernel_isolation", "drain_node", "throttle_requests",
		"alert_operators", "restart_service",
	}
	for _, action := range remediationActions {
		cognitiveEngine.RegisterRemediator(action, resolveFn)
	}
	log.Printf("BadgeConfigResolver remediator registered for %d actions", len(remediationActions))

	// Subscribe to guardrail violation events (async path)
	violationCh := cognitiveEngine.EventBus().Subscribe(cognitiveengine.EventGuardrailViolation)
	go func() {
		for evt := range violationCh {
			violation, ok := evt.Payload.(*cognitiveengine.PolicyViolation)
			if !ok || violation == nil {
				continue
			}
			signal := &wasm.ResolutionSignal{
				DVEID:   violation.DVEID,
				NodeID:  violation.NodeID,
				BadgeID: violation.BadgeID,
			}
			configResolver.Resolve(context.Background(), signal)
		}
	}()
	log.Println("Guardrail violation event bus subscribed to BadgeConfigResolver")

	log.Println("Resolution pipeline fully initialized")

	// Initialize Onboarding Service - Value System and Ontology Ingestion
	onboardingService := onboarding.NewOnboardingService(dbManager, cognitiveEngine, guardrailManager)
	log.Println("Onboarding service initialized")

	// Initialize PolicyEngine for ICME policy integration
	policyEngine := guardrails.NewPolicyEngine(dbManager, guardrailManager)
	if validationChainClient != nil {
		policyEngine.SetValidationChainClient(validationChainClient)
		log.Println("PolicyEngine: validation chain client wired for policy anchoring")
	}
	if icmeService != nil {
		icmeAdapter := &icmePolicyAdapter{icme: icmeService}
		policyEngine.SetICMEService(icmeAdapter)
		log.Println("PolicyEngine: ICME service wired for intent objective management")
	}
	if err := policyEngine.LoadPolicies(); err != nil {
		log.Printf("Warning: Failed to load policies: %v", err)
	}
	log.Println("GuardrailManager and PolicyEngine initialized")

	// Initialize Hasher gRPC Server for KNIRVHASHER integration
	//
	// IMPORTANT: The gRPC server uses a different socket path than the
	// headless HTTP server.  The gRPC socket is the one the data-connector
	// pipeline binary connects to via gRPC; the headless HTTP socket serves
	// the pipeline run/stop/status API.  They must not overlap.
	hasherSocketPath := os.Getenv("HASHER_SOCKET_PATH")
	if hasherSocketPath == "" {
		hasherSocketPath = dvemanager.DefaultSocketPath
	}
	hasherGRPCSocketPath := os.Getenv("HASHER_GRPC_SOCKET_PATH")
	if hasherGRPCSocketPath == "" {
		hasherGRPCSocketPath = hasherSocketPath[:len(hasherSocketPath)-len(".sock")] + "-grpc.sock"
	}
	hasherGRPCServer := dvemanager.NewHasherGRPCServer(hasherGRPCSocketPath, dbManager)
	if err := hasherGRPCServer.Start(); err != nil {
		log.Printf("Warning: Failed to start Hasher gRPC server: %v (hasher integration disabled)", err)
	} else {
		log.Printf("Hasher gRPC server started on %s (headless HTTP uses %s)", hasherGRPCSocketPath, hasherSocketPath)
	}

	// Initialize Hasher Client for connecting to external hasher service
	hasherIntegration := dvemanager.NewHasherIntegration(hasherGRPCSocketPath, dbManager, guardrailManager)
	if err := hasherIntegration.Connect(context.Background()); err != nil {
		log.Printf("Warning: Failed to connect to hasher gRPC service: %v (hasher validation disabled)", err)
	} else {
		log.Printf("Hasher client connected to gRPC at %s", hasherGRPCSocketPath)
	}

	// Wire hasher validator into guardrail manager for security validation
	guardrailManager.SetHasherValidator(hasherIntegration)
	log.Println("Hasher integration wired into GuardrailManager")

	// Initialize KNIRVHASHER Manager for headless pipeline subprocess
	var hasherManager *knirvhasher.Manager
	if cfg.Hasher.Enabled {
		// Extract the embedded knirvhasher binary
		hasherBinaryPath, extractErr := knirvhasher.ExtractEmbeddedBinary("")
		if extractErr != nil {
			log.Printf("Warning: Failed to extract embedded knirvhasher binary: %v", extractErr)
		} else {
			appDataDir, appDataErr := getOSAppDataDir()
			if appDataErr != nil {
				log.Printf("Warning: Failed to get app data dir for hasher: %v", appDataErr)
			} else {
				hasherConfig := cfg.Hasher
				hasherSocketPath := hasherConfig.SocketPath
				if hasherSocketPath == "" {
					hasherSocketPath = filepath.Join(appDataDir, "sockets", "hasher.sock")
				}
				hasherDataPath := hasherConfig.DataPath
				if hasherDataPath == "" {
					hasherDataPath = filepath.Join(appDataDir, "hasher")
				}
				startTimeout := time.Duration(hasherConfig.StartTimeout) * time.Second
				if startTimeout <= 0 {
					startTimeout = 30 * time.Second
				}
				stopTimeout := time.Duration(hasherConfig.StopTimeout) * time.Second
				if stopTimeout <= 0 {
					stopTimeout = 10 * time.Second
				}
				hasherMgrCfg := &knirvhasher.ManagerConfig{
					BinaryPath:     hasherBinaryPath,
					SocketPath:     hasherSocketPath,
					GRPCSocketPath: hasherGRPCSocketPath,
					DataPath:       hasherDataPath,
					HeadlessMode:   true,
					ArxivEnabled:   hasherConfig.ArxivEnabled,
					StartTimeout:   startTimeout,
					StopTimeout:    stopTimeout,
					Stdout:         logging.NewSubprocessWriter("knirvhasher", os.Stdout),
					Stderr:         logging.NewSubprocessWriter("knirvhasher", os.Stderr),
				}
				// Propagate hasher env overrides from root.key
				hasherEnvOverrides := map[string]string{}
				if rootKeySecrets != nil {
					if rootKeySecrets.DeviceIp != "" {
						hasherEnvOverrides["DEVICE_IP"] = rootKeySecrets.DeviceIp
					}
					if rootKeySecrets.DevicePassword != "" {
						hasherEnvOverrides["DEVICE_PASSWORD"] = rootKeySecrets.DevicePassword
					}
					if rootKeySecrets.DeviceUsername != "" {
						hasherEnvOverrides["DEVICE_USERNAME"] = rootKeySecrets.DeviceUsername
					}
					if rootKeySecrets.CloudflareEmbeddingsUrl != "" {
						hasherEnvOverrides["CLOUDFLARE_EMBEDDINGS_URL"] = rootKeySecrets.CloudflareEmbeddingsUrl
					}
				}
				// Propagate frames_dir from the server config YAML (not root.key)
				if hasherConfig.FramesDir != "" {
					hasherEnvOverrides["FRAMES_DIR"] = hasherConfig.FramesDir
				}
				hasherMgrCfg.EnvOverrides = hasherEnvOverrides
				hasherManager = knirvhasher.NewManager(hasherMgrCfg, logger)
				log.Printf("KNIRVHASHER manager initialized: binary=%s socket=%s data=%s headless_port=%d arxiv=%v",
					hasherBinaryPath, hasherSocketPath, hasherDataPath, hasherConfig.HeadlessPort, hasherConfig.ArxivEnabled)
			}
		}
	} else {
		log.Println("KNIRVHASHER manager disabled via configuration")
	}

	// Initialize KNIRVARENA in-process static bundle server
	var arenaManager *knirvarena.Manager
	arenaMgrConfig := knirvarena.DefaultConfig()
	arenaMgrConfig.SocketPath = arenaSocketPath
	arenaManager = knirvarena.NewManager(arenaMgrConfig, logger)
	logger.Info("KNIRVARENA manager initialized", zap.String("socket", arenaSocketPath))

	// Wire onboarding pipeline trigger to hasher data connector
	// After a successful onboarding with data ingestion, export the org data
	// and trigger the hasher pipeline for arxiv deep learning.
	onboardingService.SetPipelineTrigger(func(ctx context.Context, orgID string, config *onboarding.OrganizationConfig) error {
		if hasherIntegration == nil || !hasherIntegration.IsAvailable() {
			log.Printf("Onboarding pipeline: hasher not available, skipping pipeline trigger for org %s", orgID)
			return nil
		}
		// Trigger the data-connector pipeline path via gRPC training trigger
		resp, err := hasherIntegration.TriggerTraining(orgID, "system", hasherpb.TrainingTrigger_ON_DEMAND, map[string]string{
			"pipeline":  "data-connector",
			"mode":      "arxiv-deep-learning",
			"org_id":    orgID,
			"config_id": config.ID,
		})
		if err != nil {
			return fmt.Errorf("onboarding pipeline: failed to trigger hasher training: %w", err)
		}
		log.Printf("Onboarding pipeline triggered for org %s: training_id=%s status=%s", orgID, resp.TrainingId, resp.Status)
		return nil
	})
	log.Println("Onboarding pipeline trigger wired to hasher integration")

	// Wire EventBroadcaster to WebSocket service (will be set in setupRoutes)
	_ = eventBroadcaster

	// Create context for service lifecycle management
	ctx, cancel := context.WithCancel(context.Background())

	server := &Server{
		config:                       cfg,
		db:                           dbManager,
		router:                       router,
		p2pManager:                   p2pManager,
		logger:                       logger,
		ebpfManager:                  ebpfManager,
		virtualContainerManager:      virtualContainerManager,
		nexusServer:                  nexusServer,
		nexusAllocator:               nexusAllocator,
		dveManager:                   dveManager,
		dveCreationService:           dveCreationService,
		dveRentalService:             dveRentalService,
		validationCore:               validationCore,
		dnsService:                   dnsService,
		pluginServer:                 pluginServer,
		dataEngine:                   dataEngine,
		dveWorkspaceService:          dveWorkspaceService,
		inferenceService:             inferenceService,
		websocketService:             nil, // Will be set in setupRoutes
		teeSecurityService:           teeSecurityService,
		systemHealthService:          systemHealthService,
		fabricManagementService:      fabricManagementService,
		controllerIntegrationService: controllerIntegrationService,
		cognitiveEngine:              cognitiveEngine,
		containerOrchestrator:        containerOrchestrator,
		sessionManager:               sessionManager,
		endpointRegistry:             endpointRegistry,
		gatewayManager:               gatewayManager,
		graphManager:                 graphManager,
		graphSyncManager:             graphSyncManager,
		chainManager:                 chainManager,
		transactionChainManager:      transactionChainManager,
		validationChainManager:       validationChainManager,
		pqcManager:                   pqcManager,
		mdStorage:                    mdStorage,
		vaultService:                 vaultService,
		reasoningEngine:              reasoningEngine,
		activeMemoryService:          activeMemoryService,
		unifiedContainerManager:      unifiedContainerManager,
		agentService:                 agentService,
		knirvagentManager:            knirvagentMgr,
		icmeService:                  icmeService,
		eventBroadcaster:             eventBroadcaster,
		anchoringService:             anchoringService,
		secretManager:                secretManager,
		workflowService:              workflowService,
		rollupService:                nil,
		guardrailManager:             guardrailManager,
		policyEngine:                 policyEngine,
		knirvshellService:            knirvshellService,
		onboardingService:            onboardingService,
		hasherGRPCServer:             hasherGRPCServer,
		hasherIntegration:            hasherIntegration,
		hasherManager:                hasherManager,
		arenaManager:                 arenaManager,
		transactionChainClient:       transactionChainClient,
		validationChainClient:        validationChainClient,
		graphRAGClient:               graphRAGClient,
		ctx:                          ctx,
		cancel:                       cancel,
		running:                      false,
	}

	// Initialise oracle manager if root.key is present (root node only)
	oracleManager := initOracleManager(logger, rootKeySecrets)
	if oracleManager != nil {
		if err := oracleManager.Start(ctx); err != nil {
			logger.Error("Failed to start oracle manager — continuing without oracle", zap.Error(err))
		}

