		if err := app.backendCmd.Process.Signal(syscall.SIGTERM); err != nil {
			log.Printf("Failed to signal backend PID %d: %v — force killing", pid, err)
			app.backendCmd.Process.Kill()
			app.backendCmd.Wait() // reap the zombie

